export function buildDino(species) {
  switch (species) {
    case 'dodo': return buildDodo();
    case 'parasaur': return buildParasaur();
    case 'trike': return buildTrike();
    case 'raptor': return buildRaptor();
    case 'bronto': return buildBronto();
    case 'ptera': return buildPtera();
    default: return buildDodo();
  }
}

/* ------------------------------------------------------------------ */
/* Dino entity                                                         */
/* ------------------------------------------------------------------ */
let dinoId = 0;

export class Dino {
  constructor(species, position, world, rng = Math.random, opts = {}) {
    this.id = ++dinoId;
    this.species = species;
    this.def = SPECIES[species];
    this.world = world;
    this.rng = rng;
    this.hp = this.def.hp;
    this.maxHp = this.def.hp;
    const built = buildDino(species);
    this.group = built.group;
    this.parts = built.parts;
    this.group.position.copy(position);
    if (this.def.flying) this.group.position.y = position.y + 22 + rng() * 10;
    this.rotation = rng() * Math.PI * 2;
    this.group.rotation.y = this.rotation;
    this.home = position.clone();
    this.wanderTarget = position.clone();
    this.target = position.clone();
    this.state = 'idle';
    this.stateTimer = 1 + rng() * 3;
    this.walkPhase = rng() * 10;
    this.moving = false;
    this.tamed = opts.tamed || false;
    this.tameProgress = 0;
    this.dead = false;
    this.deadTimer = 0;
    this.harvestLeft = 0;
    this.attackCd = 0;
    this.attackAnim = 0;
    this.provoked = 0;
    this.fleeTimer = 0;
    this.mounted = false;
    this.currentSpeed = 0;
    this.roarTimer = 4 + rng() * 18;
    this.flyingAngle = rng() * Math.PI * 2;
    this.carcass = false;
    this.name = this.def.name;
    if (this.tamed) this.addCollar();
  }

  get position() { return this.group.position; }

  addCollar() {
    if (this._collar) return;
    const geo = new THREE.TorusGeometry(0.3, 0.045, 4, 12);
    const m = new THREE.Mesh(geo, new THREE.MeshStandardMaterial({ color: 0x58d6bd, emissive: 0x1b7a68, emissiveIntensity: 0.7, roughness: 0.5 }));
    const c = this.def.collar || [0, 1.2, 0.2];
    m.position.set(c[0], c[1], c[2]);
    m.rotation.x = Math.PI / 2;
    this.group.add(m);
    this._collar = m;
  }

  tame(progress = 1) {
    this.tamed = true;
    this.tameProgress = progress;
    this.provoked = 0;
    this.fleeTimer = 0;
    this.addCollar();
  }

  provoke() {
    if (this.dead) return;
    if (this.def.passive) {
      this.fleeTimer = 5;
    } else {
      this.provoked = 14;
    }
  }

  distanceTo(pos) {
    return this.position.distanceTo(pos);
  }

  faceTowards(x, z, dt, rate = 6) {
    if (Math.abs(x) < 0.001 && Math.abs(z) < 0.001) return;
    const targetAngle = Math.atan2(x, z);
    let diff = targetAngle - this.rotation;
    while (diff > Math.PI) diff -= Math.PI * 2;
    while (diff < -Math.PI) diff += Math.PI * 2;
    this.rotation += diff * (1 - Math.exp(-rate * dt));
    this.group.rotation.y = this.rotation;
  }

  moveTowards(target, speed, dt, avoidWater = true) {
    const dx = target.x - this.position.x;
    const dz = target.z - this.position.z;
    const dist = Math.hypot(dx, dz);
    if (dist < 0.25) { this.moving = false; this.currentSpeed = 0; return; }
    const step = Math.min(dist, speed * dt);
    const nx = this.position.x + (dx / dist) * step;
    const nz = this.position.z + (dz / dist) * step;
    const h = terrainHeight(nx, nz);
    if (avoidWater && h < 0.15) { this.moving = false; this.currentSpeed = 0; return; }
    this.position.x = nx;
    this.position.z = nz;
    if (!this.def.flying) this.position.y = Math.max(h, 0.05);
    this.faceTowards(dx, dz, dt, 5);
    this.walkPhase += speed * dt * 1.6;
    this.moving = true;
    this.currentSpeed = speed;
  }

  rideMove(dt, dirX, dirZ, speed) {
    const len = Math.hypot(dirX, dirZ);
    if (len < 0.01) { this.moving = false; this.currentSpeed = 0; return; }
    const nx = dirX / len, nz = dirZ / len;
    const h = terrainHeight(this.position.x + nx * 0.8, this.position.z + nz * 0.8);
    if (h > 0.1 || this.def.flying) {
      this.position.x += nx * speed * dt;
      this.position.z += nz * speed * dt;
      this.position.y = Math.max(h, 0.05);
    }
    this.faceTowards(nx, nz, dt, 8);
    this.walkPhase += speed * dt * 1.35;
    this.moving = true;
    this.currentSpeed = speed;
  }

  update(dt, game) {
    this.attackCd = Math.max(0, this.attackCd - dt);
    this.attackAnim = Math.max(0, this.attackAnim - dt);
    this.provoked = Math.max(0, this.provoked - dt);
    this.fleeTimer = Math.max(0, this.fleeTimer - dt);

    if (this.dead) {
      this.deadTimer += dt;
      this.moving = false;
      return;
    }

    if (this.def.flying) {
      this.flyingAngle += dt * 0.14;
      const r = 46 + Math.sin(this.flyingAngle * 0.7) * 12;
      const cx = this.home.x, cz = this.home.z;
      this.position.x = cx + Math.cos(this.flyingAngle) * r;
      this.position.z = cz + Math.sin(this.flyingAngle) * r;
      this.position.y = this.home.y + 26 + Math.sin(this.flyingAngle * 2.2) * 3;
      this.faceTowards(
        -Math.sin(this.flyingAngle) * r,
        Math.cos(this.flyingAngle) * r,
        dt, 3,
      );
      this.moving = true;
      this.currentSpeed = 8;
      this.animate(dt);
      return;
    }

    const player = game.player;
    const ppos = player.pos;
    const dist = this.position.distanceTo(ppos);

    if (this.tamed) {
      if (this.mounted) {
        // movement comes from rideMove() called by the game
        this.animate(dt);
        return;
      }
      const followDist = 5.5;
      if (dist > followDist + 2) {
        const ox = ppos.x + Math.sin(this.id * 1.7) * 2.2;
        const oz = ppos.z + Math.cos(this.id * 1.7) * 2.2;
        this.target.set(ox, ppos.y, oz);
        this.moveTowards(this.target, this.def.speed * 0.85, dt);
      } else {
        this.moving = false;
        this.currentSpeed = 0;
        this.faceTowards(ppos.x - this.position.x, ppos.z - this.position.z, dt, 2.5);
      }
      this.animate(dt);
      return;
    }

    // Wild behaviour
    if (this.fleeTimer > 0) {
      const away = new THREE.Vector3(
        this.position.x + (this.position.x - ppos.x) * 3,
        this.position.y,
        this.position.z + (this.position.z - ppos.z) * 3,
      );
      this.moveTowards(away, this.def.speed * 1.15, dt);
      this.animate(dt);
      return;
    }

    const safe = game.isSafeFromFire(this.position);
    let hunting = false;
    if (this.def.aggressive && !player.dead && !safe) {
      const aggro = this.def.aggro * (game.isNight ? 1.35 : 1);
      hunting = dist < aggro;
    }
    if (this.provoked > 0) hunting = true;

    if (hunting && !player.dead) {
      if (dist > this.def.reach * 0.8) {
        this.moveTowards(ppos, this.def.speed, dt);
      } else {
        this.moving = false;
        this.currentSpeed = 0;
        this.faceTowards(ppos.x - this.position.x, ppos.z - this.position.z, dt, 8);
        if (this.attackCd <= 0) {
          this.attackCd = 1.6;
          this.attackAnim = 0.35;
          game.dinoAttack(this);
        }
      }
      this.animate(dt);
      return;
    }

    // wander
    this.stateTimer -= dt;
    if (this.stateTimer <= 0) {
      this.stateTimer = 2.5 + this.rng() * 5;
      if (this.rng() < 0.42) {
        this.state = 'idle';
      } else {
        this.state = 'walk';
        const a = this.rng() * Math.PI * 2;
        const d = this.rng() * 9;
        this.wanderTarget.set(this.home.x + Math.cos(a) * d, this.position.y, this.home.z + Math.sin(a) * d);
      }
    }
    if (this.state === 'walk') {
      this.moveTowards(this.wanderTarget, this.def.wander, dt);
      if (this.position.distanceTo(this.wanderTarget) < 1) this.state = 'idle';
    } else {
      this.moving = false;
      this.currentSpeed = 0;
      // slow look around
      if (this.rng() < dt * 0.2) this.rotation += 0.5;
      this.group.rotation.y = this.rotation;
    }

    this.roarTimer -= dt;
    if (this.roarTimer <= 0 && dist < 55) {
      this.roarTimer = 18 + this.rng() * 28;
      if (this.species === 'raptor' || this.species === 'trike' || this.species === 'bronto') game.roar(this);
    }

    this.animate(dt);
  }

  animate(dt) {
    const p = this.parts;
    const t = this.walkPhase;
    const amp = this.moving ? Math.min(0.7, 0.18 + this.currentSpeed * 0.09) : 0.015;
    const len = p.legs ? p.legs.length : 0;
    for (let i = 0; i < len; i++) {
      const phase = len === 2 ? (i === 0 ? 0 : Math.PI) : (i % 2 === 0 ? 0 : Math.PI);
      p.legs[i].rotation.x = Math.sin(t + phase) * amp;
    }
    if (p.body) {
      const bob = this.moving ? Math.abs(Math.sin(t)) * 0.045 : Math.sin(t * 0.5) * 0.008;
      p.body.position.y = (p.body.userData.baseY ?? (p.body.userData.baseY = p.body.position.y)) + bob;
    }
    if (p.tail) p.tail.rotation.y = Math.sin(t * 0.6 + 1) * 0.18;
    if (p.neck) p.neck.rotation.x = Math.sin(t * 0.4) * 0.03;
    if (p.head) {
      p.head.rotation.x = Math.sin(t * 0.5 + 2) * 0.04 - this.attackAnim * 1.1;
      if (this.attackAnim > 0) p.head.rotation.x -= Math.sin(this.attackAnim * 9) * 0.3;
    }
    if (p.wings && p.wings.length) {
      for (const w of p.wings) {
        const side = w.position.x >= 0 ? 1 : -1;
        w.rotation.z = side * (Math.sin(this.walkPhase * 2 + (this.def.flying ? 0 : 0)) * 0.5 - 0.05);
      }
    }
    if (p.arms) {
      for (let i = 0; i < p.arms.length; i++) p.arms[i].rotation.x = Math.sin(t + i * Math.PI) * (this.moving ? 0.3 : 0.05);
    }
  }

  die() {
    if (this.dead) return;
    this.dead = true;
    this.hp = 0;
    this.mounted = false;
    this.moving = false;
    this.carcass = true;
    this.harvestLeft = this.def.harvestMax || 3;
    const ground = terrainHeight(this.position.x, this.position.z);
    this.group.position.y = Math.max(ground, 0.05);
    this.group.rotation.z = Math.PI / 2 * 0.85;
    this.group.rotation.x = 0.12;
    this._collar?.removeFromParent();
    this._collar = null;
  }
}

import * as THREE from 'three';

const skinMat = new THREE.MeshStandardMaterial({ color: 0xc39368, roughness: 0.8, flatShading: true });
const shirtMat = new THREE.MeshStandardMaterial({ color: 0x6f7450, roughness: 0.95, flatShading: true });
const pantsMat = new THREE.MeshStandardMaterial({ color: 0x3f4247, roughness: 0.95, flatShading: true });
const leatherMat = new THREE.MeshStandardMaterial({ color: 0x5a3c24, roughness: 0.9, flatShading: true });
const hairMat = new THREE.MeshStandardMaterial({ color: 0x2e241b, roughness: 0.95, flatShading: true });
const stoneMat = new THREE.MeshStandardMaterial({ color: 0x8a8b80, roughness: 0.95, flatShading: true });
const woodMat = new THREE.MeshStandardMaterial({ color: 0x7a532f, roughness: 0.95, flatShading: true });
const flintMat = new THREE.MeshStandardMaterial({ color: 0x4b4a44, roughness: 0.7, flatShading: true });

function box(parent, mat, size, pos, rot = [0, 0, 0]) {
  const m = new THREE.Mesh(new THREE.BoxGeometry(size[0], size[1], size[2]), mat);
  m.position.set(pos[0], pos[1], pos[2]);
  m.rotation.set(rot[0], rot[1], rot[2]);
  m.castShadow = true;
  m.receiveShadow = true;
  parent.add(m);
  return m;
}

function makeTool(kind) {
  const g = new THREE.Group();
  if (kind === 'pick' || kind === 'hatchet') {
    const handle = new THREE.Mesh(new THREE.CylinderGeometry(0.026, 0.032, 0.92, 6), woodMat);
    handle.position.y = 0.1;
    handle.castShadow = true;
    g.add(handle);
    if (kind === 'pick') {
      const head = new THREE.Mesh(new THREE.ConeGeometry(0.09, 0.55, 5), stoneMat);
      head.rotation.z = Math.PI / 2;
      head.position.set(0, 0.55, 0);
      head.castShadow = true;
      g.add(head);
      const head2 = new THREE.Mesh(new THREE.ConeGeometry(0.09, 0.5, 5), stoneMat);
      head2.rotation.z = -Math.PI / 2;
      head2.position.set(0, 0.55, 0);
      head2.castShadow = true;
      g.add(head2);
    } else {
      const blade = new THREE.Mesh(new THREE.BoxGeometry(0.3, 0.26, 0.07), stoneMat);
      blade.position.set(0.12, 0.55, 0);
      blade.rotation.z = -0.18;
      blade.castShadow = true;
      g.add(blade);
      const wrap = new THREE.Mesh(new THREE.TorusGeometry(0.075, 0.018, 4, 8), leatherMat);
      wrap.rotation.x = Math.PI / 2;
      wrap.position.y = 0.4;
      g.add(wrap);
    }
    g.position.set(0, -0.5, 0.02);
    g.rotation.x = 0.35;
    g.rotation.z = -0.1;
  } else if (kind === 'spear') {
    const shaft = new THREE.Mesh(new THREE.CylinderGeometry(0.023, 0.026, 1.75, 6), woodMat);
    shaft.position.y = 0.35;
    shaft.castShadow = true;
    g.add(shaft);
    const tip = new THREE.Mesh(new THREE.ConeGeometry(0.07, 0.34, 5), flintMat);
    tip.position.y = 1.34;
    tip.castShadow = true;
    g.add(tip);
    const lash = new THREE.Mesh(new THREE.TorusGeometry(0.05, 0.014, 4, 8), leatherMat);
    lash.rotation.x = Math.PI / 2;
    lash.position.y = 1.16;
    g.add(lash);
    g.position.set(0, -0.45, 0.04);
    g.rotation.x = 0.08;
  }
  return g;
}

export class Player {
  constructor(scene) {
    this.group = new THREE.Group();
    this.pos = this.group.position;
    this.group.position.set(0, 2, 0);
    scene.add(this.group);

    this.body = new THREE.Group();
    this.group.add(this.body);

    // hips / torso
    box(this.body, pantsMat, [0.34, 0.2, 0.24], [0, 0.92, 0]);
    box(this.body, shirtMat, [0.46, 0.56, 0.28], [0, 1.3, 0]);
    box(this.body, shirtMat, [0.52, 0.16, 0.3], [0, 1.55, 0]);
    // belt
    box(this.body, leatherMat, [0.36, 0.09, 0.26], [0, 1.02, 0]);
    // chest strap
    box(this.body, leatherMat, [0.1, 0.62, 0.03], [0.12, 1.3, 0.15], [0, 0, -0.55]);
    // backpack
    box(this.body, leatherMat, [0.38, 0.42, 0.18], [0, 1.34, -0.23]);
    box(this.body, new THREE.MeshStandardMaterial({ color: 0x7a5a38, roughness: 1, flatShading: true }), [0.3, 0.12, 0.1], [0, 1.52, -0.28]);
    // neck + head
    const neck = new THREE.Mesh(new THREE.CylinderGeometry(0.08, 0.09, 0.12, 6), skinMat);
    neck.position.set(0, 1.66, 0);
    this.body.add(neck);
    const head = new THREE.Mesh(new THREE.SphereGeometry(0.22, 10, 8), skinMat);
    head.scale.set(0.95, 1.04, 0.92);
    head.position.set(0, 1.85, 0.01);
    head.castShadow = true;
    this.body.add(head);
    const hair = new THREE.Mesh(new THREE.SphereGeometry(0.225, 8, 6), hairMat);
    hair.scale.set(1, 0.72, 1.02);
    hair.position.set(0, 1.94, -0.02);
    this.body.add(hair);
    box(this.body, hairMat, [0.16, 0.2, 0.1], [0, 1.83, -0.14]);
    // eyes
    const eyeGeo = new THREE.SphereGeometry(0.018, 5, 4);
    const eyeMat = new THREE.MeshBasicMaterial({ color: 0x17130f });
    for (const x of [0.075, -0.075]) {
      const e = new THREE.Mesh(eyeGeo, eyeMat);
      e.position.set(x, 1.86, 0.195);
      this.body.add(e);
    }
    // arms
    this.armL = new THREE.Group();
    this.armL.position.set(-0.3, 1.55, 0);
    this.body.add(this.armL);
    box(this.armL, shirtMat, [0.13, 0.44, 0.14], [0, -0.22, 0]);
    box(this.armL, skinMat, [0.11, 0.16, 0.12], [0, -0.5, 0]);
    this.armR = new THREE.Group();
    this.armR.position.set(0.3, 1.55, 0);
    this.body.add(this.armR);
    box(this.armR, shirtMat, [0.13, 0.44, 0.14], [0, -0.22, 0]);
    box(this.armR, skinMat, [0.11, 0.16, 0.12], [0, -0.5, 0]);
    this.hand = new THREE.Group();
    this.hand.position.set(0, -0.55, 0.02);
    this.armR.add(this.hand);
    this.tools = {};
    this.currentTool = null;

    // legs
    this.legL = new THREE.Group();
    this.legL.position.set(-0.14, 0.86, 0);
    this.body.add(this.legL);
    box(this.legL, pantsMat, [0.17, 0.5, 0.19], [0, -0.26, 0]);
    box(this.legL, pantsMat, [0.15, 0.34, 0.16], [0, -0.64, 0]);
    box(this.legL, leatherMat, [0.16, 0.12, 0.28], [0, -0.82, 0.04]);
    this.legR = new THREE.Group();
    this.legR.position.set(0.14, 0.86, 0);
    this.body.add(this.legR);
    box(this.legR, pantsMat, [0.17, 0.5, 0.19], [0, -0.26, 0]);
    box(this.legR, pantsMat, [0.15, 0.34, 0.16], [0, -0.64, 0]);
    box(this.legR, leatherMat, [0.16, 0.12, 0.28], [0, -0.82, 0.04]);

    // simple shoulder pad
    box(this.body, leatherMat, [0.2, 0.1, 0.24], [-0.27, 1.58, 0], [0, 0, 0.15]);

    this.walkPhase = 0;
    this.attackAnim = 0;
    this.bob = 0;
    this.riding = false;
    this.setTool('hand');
  }

  setTool(kind) {
    this.currentTool = kind;
    for (const key in this.tools) this.tools[key].visible = false;
    if (!kind || kind === 'hand') return;
    if (!this.tools[kind]) {
      const tool = makeTool(kind);
      this.tools[kind] = tool;
      this.hand.add(tool);
    }
    this.tools[kind].visible = true;
  }

  attack() {
    this.attackAnim = 1;
  }

  animate(dt, speed, moving) {
    const t = (this.walkPhase += dt * (2.2 + speed * 1.5));
    const swing = moving ? Math.min(0.72, 0.22 + speed * 0.09) : 0;
    this.legL.rotation.x = Math.sin(t) * swing;
    this.legR.rotation.x = -Math.sin(t) * swing;
    const armSwing = Math.sin(t) * swing * 0.8;
    this.armL.rotation.x = -armSwing;
    this.armL.rotation.z = 0.08;
    this.armR.rotation.x = armSwing - this.getAttackSwing();
    this.armR.rotation.z = -0.08;
    this.body.position.y = Math.abs(Math.sin(t)) * 0.035 * (moving ? 1 : 0.3);
    this.body.rotation.y = Math.sin(t) * 0.02 * (moving ? 1 : 0.2);
    this.attackAnim = Math.max(0, this.attackAnim - dt * 3.4);
    // idle breathing
    if (!moving) this.body.position.y += Math.sin(performance.now() * 0.002) * 0.008;
  }

  getAttackSwing() {
    if (this.attackAnim <= 0) return 0;
    const p = 1 - this.attackAnim;
    return Math.sin(p * Math.PI) * 2.1;
  }

  setRiding(on) {
    this.riding = on;
    this.group.visible = !on;
  }
}

export class AudioEngine {
  constructor() {
    this.ctx = null;
    this.master = null;
    this.enabled = true;
    this.ready = false;
    this._birdTimer = null;
    this._wind = null;
  }

  init() {
    if (this.ctx) {
      if (this.ctx.state === 'suspended') this.ctx.resume();
      return;
    }
    const Ctx = window.AudioContext || window.webkitAudioContext;
    if (!Ctx) return;
    try {
      this.ctx = new Ctx();
      this.master = this.ctx.createGain();
      this.master.gain.value = 0.55;
      this.master.connect(this.ctx.destination);
      this.ready = true;
      this.startWind();
      this.scheduleBirds();
    } catch {
      this.ready = false;
    }
  }

  resume() {
    if (this.ctx && this.ctx.state === 'suspended') this.ctx.resume();
  }

  setEnabled(on) {
    this.enabled = on;
    if (this.master) this.master.gain.value = on ? 0.55 : 0;
  }

  noiseBuffer(seconds = 2) {
    const len = Math.floor(this.ctx.sampleRate * seconds);
    const buffer = this.ctx.createBuffer(1, len, this.ctx.sampleRate);
    const data = buffer.getChannelData(0);
    for (let i = 0; i < len; i++) data[i] = Math.random() * 2 - 1;
    return buffer;
  }

  startWind() {
    if (!this.ctx) return;
    try {
      const src = this.ctx.createBufferSource();
      src.buffer = this.noiseBuffer(3);
      src.loop = true;
      const filter = this.ctx.createBiquadFilter();
      filter.type = 'lowpass';
      filter.frequency.value = 420;
      filter.Q.value = 0.6;
      const gain = this.ctx.createGain();
      gain.gain.value = 0.055;
      const lfo = this.ctx.createOscillator();
      lfo.frequency.value = 0.08;
      const lfoGain = this.ctx.createGain();
      lfoGain.gain.value = 0.02;
      lfo.connect(lfoGain).connect(gain.gain);
      src.connect(filter).connect(gain).connect(this.master);
      src.start();
      lfo.start();
      this._wind = { src, gain };
    } catch { /* ignore */ }
  }

  scheduleBirds() {
    if (this._birdTimer) clearTimeout(this._birdTimer);
    const next = 2600 + Math.random() * 6000;
    this._birdTimer = setTimeout(() => {
      if (this.enabled && this.ctx) this.chirp();
      this.scheduleBirds();
    }, next);
  }

  chirp() {
    if (!this.ctx || !this.enabled) return;
    const t = this.ctx.currentTime;
    for (let i = 0; i < 2 + Math.floor(Math.random() * 3); i++) {
      const start = t + i * (0.07 + Math.random() * 0.08);
      const osc = this.ctx.createOscillator();
      const gain = this.ctx.createGain();
      osc.type = 'sine';
      const base = 1500 + Math.random() * 1800;
      osc.frequency.setValueAtTime(base, start);
      osc.frequency.exponentialRampToValueAtTime(base * (1.2 + Math.random() * 0.6), start + 0.04);
      osc.frequency.exponentialRampToValueAtTime(base * 0.8, start + 0.09);
      gain.gain.setValueAtTime(0.0001, start);
      gain.gain.exponentialRampToValueAtTime(0.018, start + 0.01);
      gain.gain.exponentialRampToValueAtTime(0.0001, start + 0.11);
      osc.connect(gain).connect(this.master);
      osc.start(start);
      osc.stop(start + 0.13);
    }
  }

  tone(freq, dur, { type = 'sine', gain = 0.08, slide = 0, delay = 0 } = {}) {
    if (!this.ctx || !this.enabled) return;
    const t = this.ctx.currentTime + delay;
    const osc = this.ctx.createOscillator();
    const g = this.ctx.createGain();
    osc.type = type;
    osc.frequency.setValueAtTime(freq, t);
    if (slide) osc.frequency.exponentialRampToValueAtTime(Math.max(20, freq + slide), t + dur);
    g.gain.setValueAtTime(0.0001, t);
    g.gain.exponentialRampToValueAtTime(gain, t + 0.012);
    g.gain.exponentialRampToValueAtTime(0.0001, t + dur);
    osc.connect(g).connect(this.master);
    osc.start(t);
    osc.stop(t + dur + 0.02);
  }

  noise(dur = 0.12, { gain = 0.1, freq = 1000, q = 1, type = 'bandpass', delay = 0 } = {}) {
    if (!this.ctx || !this.enabled) return;
    const t = this.ctx.currentTime + delay;
    const src = this.ctx.createBufferSource();
    src.buffer = this.noiseBuffer(0.4);
    const filter = this.ctx.createBiquadFilter();
    filter.type = type;
    filter.frequency.value = freq;
    filter.Q.value = q;
    const g = this.ctx.createGain();
    g.gain.setValueAtTime(gain, t);
    g.gain.exponentialRampToValueAtTime(0.0001, t + dur);
    src.connect(filter).connect(g).connect(this.master);
    src.start(t);
    src.stop(t + dur + 0.02);
  }

  swing() { this.noise(0.12, { gain: 0.035, freq: 700, q: 0.8 }); }

  hitWood() {
    this.noise(0.09, { gain: 0.12, freq: 700, q: 1.4 });
    this.tone(120, 0.1, { type: 'triangle', gain: 0.07, slide: -40 });
  }
  hitStone() {
    this.noise(0.08, { gain: 0.11, freq: 2600, q: 2.2 });
    this.tone(220, 0.07, { type: 'square', gain: 0.035, slide: -60 });
  }
  hitFlesh() {
    this.noise(0.16, { gain: 0.13, freq: 300, q: 0.9, type: 'lowpass' });
    this.tone(90, 0.12, { type: 'sine', gain: 0.09, slide: -30 });
  }
  harvest() { this.tone(680, 0.08, { type: 'triangle', gain: 0.035 }); }
  footstep() { this.noise(0.07, { gain: 0.035, freq: 240, q: 0.7, type: 'lowpass' }); }
  hurt() {
    this.tone(160, 0.25, { type: 'sawtooth', gain: 0.09, slide: -90 });
    this.noise(0.2, { gain: 0.06, freq: 500, q: 0.8 });
  }
  craft() {
    this.tone(523, 0.12, { gain: 0.05 });
    this.tone(784, 0.16, { gain: 0.045, delay: 0.09 });
  }
  level() {
    this.tone(523, 0.16, { gain: 0.06 });
    this.tone(659, 0.16, { gain: 0.06, delay: 0.12 });
    this.tone(784, 0.2, { gain: 0.06, delay: 0.24 });
    this.tone(1046, 0.35, { gain: 0.055, delay: 0.36 });
  }
  tame() {
    this.tone(392, 0.16, { gain: 0.05 });
    this.tone(523, 0.18, { gain: 0.05, delay: 0.12 });
    this.tone(659, 0.26, { gain: 0.05, delay: 0.24 });
  }
  eat() {
    this.noise(0.12, { gain: 0.06, freq: 400, q: 0.8 });
    this.tone(180, 0.1, { type: 'triangle', gain: 0.04 });
  }
  drink() {
    this.tone(340, 0.12, { type: 'sine', gain: 0.05, slide: 80 });
    this.tone(420, 0.12, { type: 'sine', gain: 0.04, slide: 60, delay: 0.09 });
  }
  fire() {
    this.noise(0.2, { gain: 0.06, freq: 900, q: 0.6 });
    this.tone(140, 0.15, { type: 'triangle', gain: 0.03, slide: -20 });
  }
  roar(dino) {
    if (!this.ctx || !this.enabled) return;
    const big = dino.species === 'bronto' ? 0.6 : dino.species === 'raptor' ? 1.35 : 1;
    const base = dino.species === 'bronto' ? 46 : dino.species === 'raptor' ? 88 : 62;
    const t = this.ctx.currentTime;
    const osc = this.ctx.createOscillator();
    const g = this.ctx.createGain();
    const filter = this.ctx.createBiquadFilter();
    filter.type = 'lowpass';
    filter.frequency.value = 500 * big;
    osc.type = 'sawtooth';
    osc.frequency.setValueAtTime(base * 1.5, t);
    osc.frequency.exponentialRampToValueAtTime(base, t + 0.35);
    osc.frequency.exponentialRampToValueAtTime(base * 0.75, t + 0.9);
    g.gain.setValueAtTime(0.0001, t);
    g.gain.exponentialRampToValueAtTime(0.09 * big, t + 0.08);
    g.gain.exponentialRampToValueAtTime(0.0001, t + 1.0);
    osc.connect(filter).connect(g).connect(this.master);
    osc.start(t);
    osc.stop(t + 1.05);
    this.noise(0.7, { gain: 0.04, freq: 240, q: 0.7, type: 'lowpass' });
  }
  death() {
    this.tone(220, 0.7, { type: 'sawtooth', gain: 0.08, slide: -160 });
    this.tone(110, 1.1, { type: 'sine', gain: 0.08, slide: -60, delay: 0.15 });
  }
  click() { this.tone(900, 0.035, { type: 'square', gain: 0.025 }); }
  place() {
    this.noise(0.12, { gain: 0.08, freq: 420, q: 0.8 });
    this.tone(160, 0.12, { type: 'triangle', gain: 0.05 });
  }
}

