  const rng = mulberry32(222);
  const mat = new THREE.MeshStandardMaterial({
    color: 0x5f864b, roughness: 1, flatShading: true,
    emissive: 0x1d2c17, emissiveIntensity: 0.5,
  });
  const sandMat = new THREE.MeshStandardMaterial({ color: 0xd9c28c, roughness: 1, flatShading: true });
  const positions = [[285, -140, 26], [320, 90, 34], [-300, 170, 22]];
  for (const [x, z, s] of positions) {
    const g = new THREE.Group();
    const rock = new THREE.Mesh(new THREE.IcosahedronGeometry(1, 1), mat);
    rock.scale.set(s, s * 0.27, s * 0.7);
    rock.position.y = 1;
    const beach = new THREE.Mesh(new THREE.IcosahedronGeometry(1, 1), sandMat);
    beach.scale.set(s * 1.18, s * 0.09, s * 0.86);
    beach.position.y = 0.4;
    g.add(beach, rock);
    // jungle silhouette
    for (let i = 0; i < 4; i++) {
      const h = 8 + rng() * 7;
      const tree = new THREE.Mesh(new THREE.ConeGeometry(2.2 + rng() * 1.4, h, 5), mat);
      tree.position.set((rng() - 0.5) * s * 0.75, s * 0.26 + h * 0.32, (rng() - 0.5) * s * 0.42);
      g.add(tree);
    }
    g.position.set(x, -1, z);
    this.scene.add(g);
  }
}

