    this.camTarget.x + Math.sin(this.yaw) * cp * dist,
    this.camTarget.y + Math.sin(this.pitch) * dist,
    this.camTarget.z + Math.cos(this.yaw) * cp * dist,
  );

  // terrain collision: march from target to desired camera position
  let allowed = desired.clone();
  const steps = 14;
  for (let i = 2; i <= steps; i++) {
    const t = i / steps;
    const px = this.camTarget.x + (desired.x - this.camTarget.x) * t;
    const pz = this.camTarget.z + (desired.z - this.camTarget.z) * t;
    const py = this.camTarget.y + (desired.y - this.camTarget.y) * t;
    const h = terrainHeight(px, pz);
    if (py < Math.max(h, 0.4) + 0.55) {
      const tt = Math.max(0.12, (i - 1) / steps);
      allowed.set(
        this.camTarget.x + (desired.x - this.camTarget.x) * tt,
        this.camTarget.y + (desired.y - this.camTarget.y) * tt,
        this.camTarget.z + (desired.z - this.camTarget.z) * tt,
      );
      allowed.y = Math.max(allowed.y, h + 0.7);
      break;
    }
  }
  allowed.y = Math.max(allowed.y, 0.6);
  this.camera.position.lerp(allowed, 1 - Math.exp(-14 * dt));

